      runArg != null && _registryRef.hasMatch(stripEntry(runArg));

  /// Whether a pack registry is configured (env `DMTOOLS_PACK_REGISTRY`).
  bool get hasRegistry => _registry != null;

  /// Resolves [runArg] to a cached, verified pack.
