  /// Splits off an optional `#entry.json` override.
  static String stripEntry(String runArg) {
    final hash = runArg.indexOf('#');
    return hash >= 0 ? runArg.substring(0, hash) : runArg;
  }

  /// The `#entry.json` override, or `null`.
