  ///
  /// Returns the resolved config as a compact JSON string.
  /// Throws [ArgumentError] on invalid arguments or missing files.
  String process(List<String> args) {
    if (args.length < 2) {
      throw ArgumentError(
        'run command requires at least a file path or job name',
      );
    }
    final target = args[1];
    final runArgs = _extractRunArgs(args.sublist(2));

    // dm.ai #579: a versioned agent pack (local .zip or https URL) — resolve to
    // the unpacked, verified cache and run the entry config from there.
    final packResolver = _packResolver ?? AgentPackResolver();
    if (packResolver.isPack(target)) {
      // SOURCE_GITHUB_TOKEN authorizes private GitHub release downloads —
      // the same PropertyReader chain every other integration reads.
      final pack = packResolver.resolve(
        target,
        githubToken: PropertyReader().getGithubToken(),
      );
      return _processConfigFile(
        pack.entryFile.path,
        runArgs,
        packRoot: pack.packRoot,
      );
    }

    if (target.endsWith('.js')) {
      return _processJsFile(target, runArgs);
    }
    if (JobRegistry.isKnownJob(target) && !File(target).existsSync()) {
      return _processJobName(target, runArgs);
    }
    return _processConfigFile(target, runArgs);
  }

  // ------------------------------------------------------------------
  // Argument extraction
  // ------------------------------------------------------------------

  /// Extracts the encoded config (first non-flag arg) and `--key value`
  /// overrides from the tokens after the target.
  _RunArgs _extractRunArgs(List<String> remaining) {
    String? encodedConfig;
    final overrides = <String, String>{};
    var foundEncoded = false;
    var i = 0;
    while (i < remaining.length) {
      final arg = remaining[i];
    );
  }

  /// Loads the parent config (filesystem path or agent pack ref) and
  /// recursively resolves it. Returns the resolved config plus the pack
  /// root when the parent came from an agent pack, so the caller can
  /// resolve the child's `pack:` references against it.
  ({Map<String, dynamic> config, Directory? packRoot}) _loadAndResolve(
    String parentPath,
    String configDir,
  ) {
    if (_packResolver.isPack(parentPath)) {
      // Pack ref (local .zip / http(s) URL / <agent>@<version|latest>):
      // resolve to the unpacked cache, load the entry config from there,
      // resolve the parent's own chain inside the pack, and rewrite its
      // pack-relative paths to absolute cache paths so they keep working
      // after the merge with a child that may live in another pack or repo.
      final pack = _packResolver.resolve(
        parentPath,
        githubToken: PropertyReader().getGithubToken(),
      );
      final json =
          jsonDecode(pack.entryFile.readAsStringSync()) as Map<String, dynamic>;
      final config = resolve(json, pack.entryFile.parent.path);
      _packResolver.rewritePathsToPackRoot(config, pack.packRoot);
      // `pack:` references inside the entry config resolve against this
      // same pack.
      _rewritePackRefs(config, pack.packRoot);
      return (config: config, packRoot: pack.packRoot);
    }
    if (_packResolver.isRegistryRefShaped(parentPath) &&
        !_packResolver.hasRegistry) {
      // `<agent>@<version|latest>` shape with no registry configured: a bare
      // "file not found" here would send every machine leg debugging the
      // wrong layer — say what is actually missing.
      throw ArgumentError.value(
        parentPath,
        'parent.path',
        'is an agent-pack registry ref (<agent>@<version|latest>) but no '
            'pack registry is configured — set the DMTOOLS_PACK_REGISTRY '
            'env var to the release-registry base URL',
      );
    }
    final file = File('$configDir/$parentPath');
    final json = jsonDecode(file.readAsStringSync()) as Map<String, dynamic>;
    return (config: resolve(json, file.parent.path), packRoot: null);
  }

  /// Scheme prefix marking a config string as a reference into the resolved
  /// parent agent pack (`pack:instructions/foo.md`). Only meaningful when
  /// the config's parent is a pack.
    test('true for an https .zip URL and #entry form', () {
      expect(resolver.isPack('https://example.com/packs/x-1.0.0.zip'), isTrue);
      expect(resolver.isPack('https://example.com/x.zip#custom.json'), isTrue);
    });

    test('false for non-zip, missing file, null, non-zip URL', () {
      expect(resolver.isPack('story.json'), isFalse);
      expect(resolver.isPack('/nonexistent/pack.zip'), isFalse);
      expect(resolver.isPack(null), isFalse);
      expect(resolver.isPack('https://example.com/file.json'), isFalse);
    });
  });
}

/// Local-file resolution + path duality (AC1, AC5).
void localResolutionTests() {
  group('AgentPackResolver local resolution', () {
    test('unpacks a local pack into the cache with prefix stripped', () {
      final pack = resolver.resolve(buildPack('my_agent', '1.0.0').path);

      expect(pack.agent, 'my_agent');
      expect(pack.version, '1.0.0');
      expect(pack.entryFile.existsSync(), isTrue);
      expect(pack.entryFile.path, endsWith('my_agent.json'));
      expect(
        File(p.join(pack.packRoot.path, 'js/main.js')).existsSync(),
        isTrue,
      );
      expect(
        File(p.join(pack.packRoot.path, 'js/common/util.js')).existsSync(),
        isTrue,
      );
      expect(
        File(p.join(pack.packRoot.path, 'agents/js/main.js')).existsSync(),
        isFalse,
      );
    });

    test('second resolve of the same version is a cache hit', () {
      final zip = buildPack('my_agent', '1.0.0');
      final first = resolver.resolve(zip.path);
      final marker = File(p.join(first.packRoot.path, 'MARKER.txt'))
        ..writeAsStringSync('cached');
      final second = resolver.resolve(zip.path);
      expect(marker.existsSync(), isTrue, reason: 'cache hit keeps the dir');
      expect(second.packRoot.path, first.packRoot.path);
    });
  });
}

/// The `#entry.json` override (AC7).
void entryOverrideTests() {
  group('AgentPackResolver entry override', () {
    test('#entry override resolves an in-pack config', () {
      // custom.json is the parent of my_agent.json, so it lands in the closure.
      write('js/main.js', '// main\n');
      write(
        'custom.json',
        jsonEncode({
          'name': 'X',
          'params': {'jsPath': 'agents/js/main.js'},
        }),
      );
      final entry = write(
        'my_agent.json',
        jsonEncode({
          'name': 'X',
          'parent': {'path': 'agents/custom.json'},
          'params': <String, dynamic>{},
        }),
      );

{"path":"/home/runner/work/dmtools-dart/dmtools-dart/lib/src/pack/pack_provenance.dart","content":"/// Provenance of an installed agent pack (gh-375): which zip the cached
/// directory was unpacked from. Two releases can share a pack version with
/// different content, so the cache is keyed on the zip's SHA-256 and the
/// source URL (which carries the registry base), not on name+version alone.
library;

import 'dart:convert';
import 'dart:io';

import 'package:path/path.dart' as p;

/// File name written at the root of every unpacked pack directory.
const String packProvenanceFileName = '.provenance.json';

/// Identity of the zip an unpacked pack directory came from.
class PackProvenance {
  /// Creates a provenance record.
  const PackProvenance({
    required this.name,
    required this.version,
    required this.sha256,
    required this.sourceUrl,
  });

  /// Decodes a record written by [toJson]; `null` when malformed.
  static PackProvenance? fromJson(Object? json) {
    if (json is! Map) return null;
    final name = json['name'];
    final version = json['version'];
    final sha = json['sha256'];
    final source = json['sourceUrl'];
    if (name is! String ||
        version is! String ||
        sha is! String ||
        source is! String) {
      return null;
    }
    return PackProvenance(
        name: name, version: version, sha256: sha, sourceUrl: source);
  }

  /// Agent name from the manifest.
  final String name;

  /// Pack version from the manifest.
  final String version;

  /// Lower-case hex SHA-256 of the zip the pack was unpacked from.
  final String sha256;

  /// Download URL, local zip path, or registry-resolved URL of the zip.
  final String sourceUrl;

  /// JSON map persisted as [packProvenanceFileName].
  Map<String, String> toJson() => {
        'name': name,
        'version': version,
        'sha256': sha256,
        'sourceUrl': sourceUrl,
      };

  /// True when [other] describes the same zip content from the same source.
  bool matches(PackProvenance? other) =>
      other != null &&
      other.name == name &&
      other.version == version &&
      other.sha256 == sha256 &&
      other.sourceUrl == sourceUrl;

  /// One actionable log line naming the pack, version, sha and source.
  String describe() =>
      'pack provenance: name=$name version=$version sha256=$sha256 '
      'source=$sourceUrl';

  /// Reads the provenance record stored under [packRoot]; `null` when absent
  /// or unreadable (treated as a cache miss by the resolver).
  static PackProvenance? read(Directory packRoot) {
    final file = File(p.join(packRoot.path, packProvenanceFileName));
    if (!file.existsSync()) return null;
    try {
      return fromJson(jsonDecode(file.readAsStringSync()));
    } on FormatException {
      return null;
    }
  }

  /// Writes this record under [packRoot].
  void write(Directory packRoot) {
    File(p.join(packRoot.path, packProvenanceFileName))
        .writeAsStringSync(jsonEncode(toJson()));
  }
}
"}

